local function bx(a,b)
  local r,bit=0,1
  for _=1,8 do
    local aa,bb=a%2,b%2
    if aa~=bb then r=r+bit end
    a,b=(a-aa)/2,(b-bb)/2
    bit=bit*2
  end
  return r
end
