local Hs=game:GetService("HttpService")
local raw=table.concat(_c)
local ok,x=pcall(function() return Hs:Base64Decode(raw) end)
if not ok or type(x)~="string" then error("[VannHUB] b64 fail") end
local t={}
for i=1,#x do
  local kb=string.byte(_k, ((i-1)%#_k)+1)
  t[i]=string.char(bx(string.byte(x,i), kb))
end
local ok2,src=pcall(function() return Hs:Base64Decode(table.concat(t)) end)
if not ok2 or type(src)~="string" then error("[VannHUB] decode fail") end
local fn,err=loadstring(src)
if not fn then error("[VannHUB] load fail: "..tostring(err)) end
return fn()